\begin{thebibliography}{99}

\bibitem{butler2003}
Butler, E. A., Egloff, B., Wilhelm, F. H., et al. (2003). The social consequences of expressive suppression. \textit{Emotion}, 3(1), 48-67.

\bibitem{gross2003}
Gross, J. J., \& John, O. P. (2003). Individual differences in two emotion regulation processes: Implications for affect, relationships, and well-being. \textit{Journal of Personality and Social Psychology}, 85(2), 348-362.

\end{thebibliography}

\end{document}

